commands:
# Get all GPUs
 $gpus = Get-CimInstance Win32_VideoController | Select-Object -ExpandProperty PNPDeviceID

 foreach ($gpu in $gpus) {
  $baseKey = "HKLM:\SYSTEM\CurrentControlSet\Enum\$gpu\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties"
  if (Test-Path $baseKey) {
  Set-ItemProperty -Path $baseKey -Name "MSISupported" -Value 1
  }

  $affinityKey = "HKLM:\SYSTEM\CurrentControlSet\Enum\$gpu\Device Parameters\Interrupt Management\Affinity Policy"
  if (Test-Path $affinityKey) {
  Set-ItemProperty -Path $affinityKey -Name "DevicePriority" -Value 0
  }
 }

